import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def verify_webhook_signature(payload, signature):
    """Verify incoming webhook signatures from integration partners."""
    secret = os.environ.get('WEBHOOK_SECRET', 'default-dev-key')
    expected = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    """Remove potentially dangerous characters but preserve extension."""
    name = secure_filename(filename)
    # Additional sanitization for special chars
    for ch in [';', '&', '|', '`', '$', '(', ')']:
        name = name.replace(ch, '_')
    return name

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    # Check file size
    file.seek(0, os.SEEK_END)
    size = file.tell()
    file.seek(0)
    if size > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    safe_name = sanitize_filename(file.filename)

    # Create temp working directory
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)
    input_path = os.path.join(work_dir, safe_name)
    file.save(input_path)

    # Get output format from query parameter
    output_format = request.args.get('format', 'pdf')

    # Build LibreOffice conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {work_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr[:200]}), 500

        # Find the output file
        output_name = os.path.splitext(safe_name)[0] + '.' + output_format.split(':')[0]
        output_path = os.path.join(work_dir, output_name)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup is handled by a cron job on /tmp/conversions
        pass

@app.route('/api/v2/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint for enterprise customers."""
    api_key = request.headers.get('X-API-Key')
    if not api_key or len(api_key) < 32:
        return jsonify({'error': 'Valid API key required'}), 401

    files = request.files.getlist('files')
    if not files or len(files) > 20:
        return jsonify({'error': 'Provide 1-20 files'}), 400

    results = []
    for f in files:
        if allowed_file(f.filename):
            results.append({'file': f.filename, 'status': 'queued'})

    return jsonify({'batch_id': hashlib.md5(api_key.encode()).hexdigest(), 'results': results})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
